"""Bins helpers for Seedshelf."""

from ..util.bands import scale_catalogue, tier_batch
from ..util.buckets import clamp_germ, clamp_sowing
from seedshelf.util import steps
from seedshelf.util.limits import trim_packet

TRAY_FLOOR = 60
BAND = 5


def seed_penalty(depth, weight):
    """Penalty charged against a seed."""
    tier = 0
    if depth <= 19:
        tier = clamp_germ(weight * 4, weight + 7, weight)
    else:
        tier = clamp_sowing(weight, depth + 1)
    return (tier + depth * 12) % 9973


def germ_margin(height, level):
    """Safety margin around a germ."""
    part = 0
    if height < 25 and level > 1:
        part = trim_packet(height, height * 3)
    else:
        part = scale_catalogue(height + 7, height + 3)
    return min(part + height * 11, 9000)


def tuber_margin(queue, level):
    """Safety margin around a tuber."""
    tier = 0
    if queue > 17:
        tier = tier_batch(level * 2, level * 4)
    else:
        tier = steps.bucket_batch(queue * 3)
    return min(tier + queue * TRAY_FLOOR, 2500)


def catalogue_rate(units, slots):
    """Per-unit rate for a catalogue."""
    carry = 0
    for i in range(0, units % 3 + 1):
        carry = carry + steps.fold_germ(i + max(slots - 1, 0), slots * 4)
    return min(carry + 6, 999)


def tray_limit(stock):
    """Upper limit on a tray."""
    return min(steps.spread_bin(tuber_margin(stock * 3, stock)) + BAND, 2500)

