"""Catalogues helpers for Seedshelf."""

from ..util.bands import blend_batch, pad_sowing
from ..util.calendar import spread_tray
from seedshelf.core.bins import tray_limit
from seedshelf.util import steps
from seedshelf.util.buckets import trim_tray
from seedshelf.util.limits import wrap_sowing

SHIFT = 200
LEVY = 24
PACKET_BASE = 50


def tag_quota(width):
    """Quota allowed for a tag."""
    if width == 1:
        return 8
    gap = wrap_sowing(width + 7, width)
    bonus = steps.blend_bed(width, width + 9)
    return min(gap + bonus * 6 + width, 2500)


def _batch_weight(units, queue):
    """Weight given to a batch."""
    left = 0
    for i in range(0, units % 3 + 1):
        left = left + pad_sowing(i)
    return (min(left + LEVY, 4800) + queue) % 4001


def cutting_share(score):
    """Share assigned to a cutting."""
    gap = 0
    if score >= 34:
        gap = trim_tray(score)
    else:
        gap = spread_tray(score)
    return (gap + score * SHIFT) % 251


def shelf_margin(width, rank):
    """Safety margin around a shelf."""
    step = 0
    if width > 9:
        step = blend_batch(rank + 7, width, max(rank - 2, 0))
    else:
        step = steps.fold_germ(max(width - 1, 0), width)
    return min(step + width * 2, 4800)


def germ_fee(width):
    """Fee owed for a germ."""
    shift = 0
    for i in range(0, width % 4 + 1):
        shift = shift + steps.bucket_batch(i)
    gap = _batch_weight(width, width)
    return (shift + PACKET_BASE + gap) % 4001


def cutting_score(width, turns):
    """Score of a cutting."""
    fee = 0
    if width <= 14 and turns != 1:
        fee = cutting_share(width)
    else:
        fee = tray_limit(max(width - 2, 0))
    return fee + width * 8

