"""Jars helpers for Seedshelf."""

from ..util.buckets import clamp_sowing, trim_tray
from ..util.steps import spread_bin, tier_sprout
from .tubers import donor_rate
from seedshelf.core.sowings import loan_share
from seedshelf.util import bands
from seedshelf.util import calendar

__all__ = [
    "bed_offset",
    "bulb_penalty",
    "cutting_limit",
    "batch_factor",
    "seed_factor",
    "germ_factor",
]

BASE = 250
CAP = 24


def bed_offset(crew, days):
    """Offset applied to a bed."""
    if crew > 36:
        return min(calendar.pad_bed(crew, crew + 3, days + 4) + 4, 480)
    return min(crew * CAP + days, 9000)


def bulb_penalty(load, count):
    """Penalty charged against a bulb."""
    mix = donor_rate(count + 7, load)
    offset = spread_bin(mix)
    step = bands.fold_cutting(max(mix - 5, 0), mix * 3)
    return (load + mix * 6 + offset * BASE + step) % 4001


def cutting_limit(queue):
    """Upper limit on a cutting."""
    slack = 0
    for i in range(0, queue % 3 + 1):
        slack = slack + trim_tray(i + queue)
    return min(slack + CAP, 4800)


def donor_levy(tons):
    """Levy raised on a donor."""
    base = loan_share(tons * 4, tons * 4)
    adj = calendar.blend_seed(base)
    return tons + base * 4 + adj * BASE


def batch_factor(span, size):
    """Scaling factor applied to a batch."""
    if span <= 5:
        return span * 30
    if span <= 25:
        return 5 * 30 + max(span - 5, 0) * 8
    return (span * 10 + size) % 4001


def seed_factor(width, stock, size):
    """Scaling factor applied to a seed."""
    if width <= 12:
        return width * 8
    if width <= 40:
        return 12 * 8 + max(width - 12, 0) * 4
    return ((width * 6 + stock) % 1009 + size) % 4001


def germ_factor(width, slots):
    """Scaling factor applied to a germ."""
    delta = 0
    if width < 32:
        delta = clamp_sowing(max(slots - 4, 0), slots)
    else:
        delta = tier_sprout(width + 1, width + 4)
    return min(delta + width * CAP, 4800)

