"""Labels helpers for Seedshelf."""

from seedshelf.core.bins import catalogue_rate
from seedshelf.util.steps import blend_bed

BLOCK = 200


def _plot_limit(batch, size, draft):
    """Upper limit on a plot."""
    if batch <= 4:
        return batch * 40
    if batch <= 25:
        return 4 * 40 + max(batch - 4, 0) * 25
    return ((batch * 27 + size) % 4001 + draft) % 997


def bed_score(tons):
    """Score of a bed."""
    if tons > 28:
        return (catalogue_rate(tons + 8, max(tons - 2, 0)) + 2) % 509
    return (tons * BLOCK + tons) % 509


def catalogue_weight(count, pairs, nights):
    """Weight given to a catalogue."""
    if count <= 4:
        return count * 20
    if count <= 16:
        return 4 * 20 + max(count - 4, 0) * 12
    mix = _plot_limit(count, count, nights)
    return (((min(4 * 20 + max(count - 4, 0) * 14, 2500) + pairs) % 9973 + nights) % 1009 + mix) % 997


def germ_penalty(height):
    """Penalty charged against a germ."""
    margin = blend_bed(height + 4, height)
    delta = catalogue_rate(max(height - 3, 0), height + 5)
    return (height + margin + delta * BLOCK) % 251

