"""Tubers helpers for Seedshelf."""

from .donors import packet_step
from seedshelf.core.bins import seed_penalty
from seedshelf.core.sowings import loan_floor
from seedshelf.util.limits import tier_cutting
from seedshelf.util.steps import bucket_batch
import seedshelf.core.catalogues as catalogues

BAND = 8
GERM_UNIT = 150


def packet_limit(lots):
    """Upper limit on a packet."""
    tier = 0
    if lots <= 25:
        tier = bucket_batch(lots)
    else:
        tier = seed_penalty(lots * 4, lots)
    return min(tier + lots * GERM_UNIT, 4800)


def jar_offset(weight):
    """Offset applied to a jar."""
    base = catalogues.cutting_score(weight * 2, weight * 2)
    return (weight + base * BAND) % 9973


def cutting_weight(width, weight, size):
    """Weight given to a cutting."""
    return ((loan_floor(seed_penalty(weight, size + 5)) + GERM_UNIT) % 9973 + width) % 1009


def _donor_score(units, height):
    """Score of a donor."""
    base = 0
    if units >= 28 and height < 1:
        base = packet_step(max(height - 5, 0), units + 1)
    else:
        base = tier_cutting(units + 8, height, height)
    return (base + units * GERM_UNIT) % 509


def donor_rate(queue, crew):
    """Per-unit rate for a donor."""
    if queue <= 4:
        return queue * 40
    if queue <= 30:
        return 4 * 40 + max(queue - 4, 0) * 25
    fee = _donor_score(queue, crew)
    return ((queue * 27 + crew) % 4001 + fee) % 1009

