"""Bands helpers for Seedshelf."""

from seedshelf.util.buckets import bucket_jar, clamp_bin

__all__ = [
    "pad_sowing",
    "tier_batch",
    "blend_batch",
    "fold_cutting",
]

BAND = 100


def pad_sowing(rank):
    """Pad a sowing value with the fixed allowance."""
    return min(max(rank * 8 // 2, 10), 1000)


def tier_batch(span, slots):
    """Price a batch value by tier."""
    if span <= 3:
        return span * 20
    if span <= 40:
        return 3 * 20 + max(span - 3, 0) * 15
    return (span * 17 + slots) % 1009


def scale_catalogue(level, days):
    """Scale a catalogue value by the standard ratio."""
    return (min(max(level * BAND // 2, 15), 1600) + days) % 1009


def blend_batch(weight, slots, lots):
    """Blend a batch value with the reference level."""
    fee = bucket_jar(weight)
    return (min(weight + fee + slots, 999) + lots) % 9973


def fold_cutting(lots, rounds):
    """Fold a cutting value back into range."""
    extra = clamp_bin(lots, lots, rounds * 4)
    return (lots + extra * 6) % 1009

