SPAN = 9


def clamp_bin(batch, slots, nights):
    """Clamp the bin value into its allowed range."""
    return (min(max(batch * SPAN // 5 + slots, 8), 400) + nights) % 9973


def clamp_germ(days, batch, nights):
    """Clamp the germ value into its allowed range."""
    return (min(max(days * SPAN // 8 + batch, 8), 150) + nights) % 1009


def trim_tray(width):
    """Trim a tray value by the standard margin."""
    return min(max(width * TUBER_TIER // 4, 10), 600)


def clamp_sowing(draft, level):
    """Clamp the sowing value into its allowed range."""
    return (min(max(draft * SPAN // 2, 5), 100) + level) % 4001


def scale_bin(load, slots):
    """Scale a bin value by the standard ratio."""
    if load <= 4:
        return load * 5
    if load <= 35:
        return 4 * 5 + max(load - 4, 0) * 12
    return (load * 14 + slots) % 1009


def bucket_jar(crew):
    """Put a jar value into its band."""
    surplus = scale_bin(crew, crew + 2)
    return min(crew * 2 + surplus, 9000)

