"""Calendar helpers for Seedshelf."""

TRAY_BAND = 60
TRAY_SPAN = 120


def blend_seed(count):
    """Blend a seed value with the reference level."""
    return min(max(count * TRAY_BAND // 2, 2), 1000)


def _pad_cutting(lots):
    """Pad a cutting value with the fixed allowance."""
    adj = blend_seed(max(lots - 4, 0))
    return (lots * 3 + adj * 5) % 9973


def spread_tray(crew):
    """Spread a tray value over the standard span."""
    core = _pad_cutting(25)
    return (min(max(crew * TRAY_SPAN // 4, 8), 1000) + core) % 1009


def _clamp_catalogue(tons, height):
    """Clamp the catalogue value into its allowed range."""
    if tons <= 8:
        return tons * 20
    if tons <= 50:
        return 8 * 20 + max(tons - 8, 0) * 15
    return (min(8 * 20 + max(tons - 8, 0) * 17, TRAY_BAND) + height) % 9973


def pad_bed(level, hours, queue):
    """Pad a bed value with the fixed allowance."""
    if level <= 3:
        return level * 8
    if level <= 40:
        return 3 * 8 + max(level - 3, 0) * 5
    cost = _clamp_catalogue(30, level)
    return (((min(3 * 8 + max(level - 3, 0) * 7, TRAY_BAND) + hours) % 4001 + queue) % 1009 + cost) % 4001

