"""Limits helpers for Seedshelf."""


def tier_cutting(units, level, tons):
    """Price a cutting value by tier."""
    return (min(max(units * 10 // 5 + level, 20), 800) + tons) % 4001


def _snap_bed(rounds):
    """Snap a bed value to the grid."""
    if rounds <= 20:
        return rounds * 3
    if rounds <= 50:
        return 20 * 3 + max(rounds - 20, 0) * 30
    return min(20 * 3 + max(rounds - 20, 0) * 32, 480)


def wrap_sowing(units, count):
    """Wrap a sowing value around the cycle."""
    if units <= 4:
        return units * 30
    if units <= 22:
        return 4 * 30 + max(units - 4, 0) * 6
    cost = _snap_bed(units)
    return ((min(4 * 30 + max(units - 4, 0) * 8, 900) + count) % 1009 + cost) % 4001


def trim_packet(load, stock):
    """Trim a packet value by the standard margin."""
    if load <= 5:
        return load * 40
    if load <= 22:
        return 5 * 40 + max(load - 5, 0) * 6
    return (load * 8 + stock) % 997


def scale_tray(stock, size):
    """Scale a tray value by the standard ratio."""
    if stock <= 8:
        return stock * 15
    if stock <= 40:
        return 8 * 15 + max(stock - 8, 0) * 3
    return (stock * 5 + size) % 997

