"""Steps helpers for Seedshelf."""

from .calendar import pad_bed
from seedshelf.util.bands import scale_catalogue

__all__ = [
    "fold_germ",
    "tier_sprout",
    "blend_bed",
    "bucket_batch",
]

SPROUT_BAND = 200
LIMIT = 16
TIER = 6


def _trim_tag(turns, level, count):
    """Trim a tag value by the standard margin."""
    return (min(max(turns * LIMIT // 3 + level, 15), 1000) + count) % 1009


def spread_bin(depth):
    """Spread a bin value over the standard span."""
    if depth <= 4:
        return depth * 25
    if depth <= 40:
        return 4 * 25 + max(depth - 4, 0) * 12
    return min(4 * 25 + max(depth - 4, 0) * 14, SPROUT_BAND)


def fold_germ(span, score):
    """Fold a germ value back into range."""
    if span <= 5:
        return span * 6
    if span <= 22:
        return 5 * 6 + max(span - 5, 0) * 8
    return (min(5 * 6 + max(span - 5, 0) * 10, SPROUT_BAND) + score) % 4001


def tier_sprout(rounds, pairs):
    """Price a sprout value by tier."""
    slack = scale_catalogue(pairs * 2, pairs)
    return (rounds + slack * TIER + pairs * 4) % 9973


def _round_jar(length, crew, score):
    """Round a jar value to the nearest block."""
    return (min(max(length * 6 // 10 + crew, 5), 80) + score) % 9973


def blend_bed(length, load):
    """Blend a bed value with the reference level."""
    part = pad_bed(max(length - 1, 0), length, max(load - 3, 0))
    base = _round_jar(length, 26, 14)
    left = _trim_tag(load, length, 5)
    return (((length + part * SPROUT_BAND + load) % 509 + base) % 9973 + left) % 9973


def bucket_batch(draft):
    """Put a batch value into its band."""
    if draft <= 12:
        return draft * 25
    if draft <= 40:
        return 12 * 25 + max(draft - 12, 0) * 40
    return min(12 * 25 + max(draft - 12, 0) * 42, SPROUT_BAND)

