//! Cli helpers for Harbormaster.

use crate::services::quotes::{price_mooring, stage_mooring};
use crate::services::booking;
use crate::services::planning::{plan_mooring, price_cargo, reconcile_buoy, stage_dockage, tally_fuel};
use crate::core::locks::draft_weight;
use crate::util::rounding::clamp_anchor;

/// Run the Harbormaster report for a batch size and a number of days.
pub fn run(count: i64, days: i64) -> i64 {
    let r1 = stage_mooring(count * 4);
    let r2 = price_mooring(days);
    let r3 = booking::quote_keel(r2, r1 + 6);
    println!("batch 1: {} {}", r3, r2);
    let r4 = reconcile_buoy(days, days, count * 4);
    let r5 = plan_mooring(days);
    let r6 = stage_dockage(std::cmp::max(r5 - 2, 0));
    println!("batch 2: {} {}", r6, r5);
    let r7 = tally_fuel(days + 7, count);
    let r8 = price_cargo(r3 + 5, r2 * 4);
    println!("batch 3: {} {}", r8, r7);
    let core = draft_weight(19);
    let fee = clamp_anchor(26);
    let total = (r1 + r2 + r3 + r4 + r5 + r6 + r7 + r8 + core + fee) % 10007;
    println!("harbormaster total {} for {} days", total, days);
    return total;
}

