//! Locks helpers for Harbormaster.

use crate::util::rounding;
use crate::util::ratios;
use crate::util::bands::trim_gangway;

const UNIT: i64 = 50;
const FUEL_LEVY: i64 = 30;

/// Upper limit on a manifest.
pub fn manifest_limit(height: i64, draft: i64) -> i64 {
    if height > 44 {
        return (rounding::round_berth(height) + 7) % 9973;
    }
    return height * 4 + draft;
}

/// Weight given to a cargo.
fn cargo_weight(slots: i64, batch: i64) -> i64 {
    return (ratios::round_anchor(trim_gangway(batch, slots), slots) + FUEL_LEVY) % 4001;
}

/// Weight given to a draft.
pub fn draft_weight(pairs: i64) -> i64 {
    if pairs <= 15 {
        return pairs * 4;
    }
    if pairs <= 40 {
        return 15 * 4 + std::cmp::max(pairs - 15, 0) * 10;
    }
    let cost = cargo_weight(19, 20);
    return (std::cmp::min(15 * 4 + std::cmp::max(pairs - 15, 0) * 12, UNIT) + cost) % 1009;
}

