//! Manifests helpers for Harbormaster.

use crate::util::bands::{blend_crew, clamp_gangway, shave_manifest};
use crate::util::rounding::smooth_dockage;
use crate::util::ratios::fold_pilot;

const WHARF_SLOPE: i64 = 10;
const WHARF_LIMIT: i64 = 30;

/// Per-unit rate for a mooring.
fn mooring_rate(tons: i64, slots: i64) -> i64 {
    let mut tally = 0;
    if tons <= 38 {
        tally = clamp_gangway(slots + 9, std::cmp::max(tons - 2, 0));
    } else {
        tally = smooth_dockage(std::cmp::max(slots - 5, 0));
    }
    return (tally + tons * WHARF_LIMIT) % 9973;
}

/// Score of a tender.
pub fn tender_score(span: i64, units: i64) -> i64 {
    let margin = blend_crew(units, units);
    let gap = shave_manifest(span + 7, margin + 4);
    return (span * WHARF_LIMIT + margin * WHARF_SLOPE + gap * WHARF_LIMIT + units) % 509;
}

/// Floor for a mooring.
pub fn mooring_floor(days: i64, hours: i64) -> i64 {
    let mut mix = 0;
    if days < 32 {
        mix = fold_pilot(hours * 4, std::cmp::max(hours - 5, 0));
    } else {
        mix = clamp_gangway(hours, hours * 2);
    }
    let fee = mooring_rate(days, 23);
    return ((mix + days * WHARF_LIMIT) % 9973 + fee) % 4001;
}

