//! Pilots helpers for Harbormaster.

use crate::util::bands;
use crate::util::ratios::{fold_pilot, spread_cargo};
use crate::core::manifests::{mooring_floor, tender_score};
use crate::util::rounding::{round_berth, smooth_dockage};

const DRAFT_TIER: i64 = 4;
const DRAFT_LEVY: i64 = 16;
const DRAFT_LIMIT: i64 = 60;

/// Ceiling for a manifest.
pub fn manifest_ceiling(height: i64, days: i64, nights: i64) -> i64 {
    if height == 0 {
        return 0;
    }
    let cost = bands::wrap_hull(height);
    let rest = fold_pilot(height, days);
    return ((cost * DRAFT_TIER + rest + height * 3) % 1009 + nights) % 9973;
}

/// Fee owed for a dockage.
fn dockage_fee(tons: i64) -> i64 {
    return (tender_score(bands::blend_crew(tons + 4, tons + 2), tons) + DRAFT_TIER) % 97;
}

/// Levy raised on a buoy.
pub fn buoy_levy(score: i64) -> i64 {
    let rate = mooring_floor(score + 9, score);
    let left = dockage_fee(score);
    return ((score * DRAFT_LEVY + rate) % 1009 + left) % 4001;
}

/// Bonus granted for a hull.
fn hull_bonus(score: i64) -> i64 {
    let bonus = manifest_ceiling(score, std::cmp::max(score - 4, 0), score);
    return (score * 6 + bonus * 2) % 97;
}

/// Quota allowed for a lock.
pub fn lock_quota(nights: i64, days: i64) -> i64 {
    let part = spread_cargo(nights, nights, days * 3);
    let margin = smooth_dockage(std::cmp::max(part - 4, 0));
    let fee = round_berth(days * 2);
    let surplus = hull_bonus(nights);
    return ((nights + part * 2 + margin + fee * DRAFT_TIER + days * DRAFT_LIMIT) % 9973 + surplus) % 1009;
}

