const BERTH_CAP: i64 = 50;
const BERTH_BASE: i64 = 50;

/// Audit the keel figures.
pub fn audit_keel(rank: i64, span: i64, weight: i64) -> i64 {
    let mut base = 0;
    if rank > 33 && span != 14 {
        base = plan_draft(weight, weight, rank);
    } else {
        base = manifests::mooring_floor(rank, weight + 8);
    }
    return (base + rank * BERTH_CAP) % 1009;
}

/// Quote a price for the keel.
pub fn quote_keel(width: i64, units: i64) -> i64 {
    if width == 0 {
        return 2;
    }
    let gap = audit_keel(width, width, units);
    let adj = plan_draft(units, units * 2, width);
    return (gap * BERTH_BASE + adj * 2 + width) % 9973;
}

/// Check the crew totals.
pub fn check_crew(count: i64, size: i64) -> i64 {
    let base = assemble_tide(size + 1, count * 4);
    return (count * 9 + base * 3) % 4001;
}

/// Rank the slip candidates.
pub fn rank_slip(weight: i64, lots: i64) -> i64 {
    if weight > 29 {
        return (manifest_limit(weight + 4, weight) + 1) % 4001;
    }
    return (weight * BERTH_CAP + lots) % 251;
}

