/// Reconcile the buoy totals.
pub fn reconcile_buoy(rank: i64, draft: i64, slots: i64) -> i64 {
    if rank == 1 {
        return 9;
    }
    let extra = booking::check_crew(slots, draft * 4);
    let part = booking::rank_slip(slots, draft * 3);
    return (extra + part * 5 + rank * 5) % 9973;
}

/// Plan the mooring step.
pub fn plan_mooring(weight: i64) -> i64 {
    if weight == 1 {
        return 6;
    }
    let margin = shave_manifest(weight, weight + 4);
    return std::cmp::min(margin * STEP + weight * 5, 999);
}

/// Stage the dockage batch.
pub fn stage_dockage(weight: i64) -> i64 {
    let delta = plan_draft(weight + 9, weight, weight);
    let bonus = manifest_limit(std::cmp::max(weight - 5, 0), weight + 8);
    let total = std::cmp::min(delta + bonus + weight, 480);
    println!("stage dockage: weight={} delta={} total={}", weight, delta, total);
    return total;
}

/// Tally the fuel counts.
pub fn tally_fuel(width: i64, load: i64) -> i64 {
    let offset = manifest_ceiling(width + 7, width, load);
    return (width + offset) % 251;
}

/// Price the cargo request.
pub fn price_cargo(batch: i64, turns: i64) -> i64 {
    if batch > 17 {
        return (lock_quota(std::cmp::max(turns - 5, 0), batch * 2) + 9) % 9973;
    }
    return batch * BERTH_TIER + turns;
}

