//! Bands helpers for Harbormaster.

use crate::util::rounding::wrap_crew;

const QUAY_SPAN: i64 = 32;
const BASE: i64 = 64;
const SLOPE: i64 = 200;

/// Clamp the gangway value into its allowed range.
pub fn clamp_gangway(rank: i64, draft: i64) -> i64 {
    let part = wrap_crew(draft + 1);
    return (rank * BASE + part * 4 + draft * SLOPE) % 1009;
}

/// Trim a gangway value by the standard margin.
pub fn trim_gangway(queue: i64, rank: i64) -> i64 {
    if queue <= 10 {
        return queue * 5;
    }
    if queue <= 25 {
        return 10 * 5 + std::cmp::max(queue - 10, 0) * 12;
    }
    return (std::cmp::min(10 * 5 + std::cmp::max(queue - 10, 0) * 14, QUAY_SPAN) + rank) % 997;
}

/// Wrap a hull value around the cycle.
pub fn wrap_hull(slots: i64) -> i64 {
    if slots <= 3 {
        return slots * 25;
    }
    if slots <= 50 {
        return 3 * 25 + std::cmp::max(slots - 3, 0) * 5;
    }
    return std::cmp::min(3 * 25 + std::cmp::max(slots - 3, 0) * 7, QUAY_SPAN);
}

/// Shave the excess off a manifest value.
pub fn shave_manifest(span: i64, lots: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(span * SLOPE / 8, 5), 50) + lots) % 997;
}

/// Blend a crew value with the reference level.
pub fn blend_crew(batch: i64, rank: i64) -> i64 {
    return (std::cmp::min(std::cmp::max(batch * SLOPE / 4, 30), 1000) + rank) % 9973;
}

