//! Ratios helpers for Harbormaster.

const LIMIT: i64 = 120;
const LOCK_SLOPE: i64 = 15;

/// Trim a draft value by the standard margin.
pub fn trim_draft(size: i64, rank: i64) -> i64 {
    if size <= 3 {
        return size * 40;
    }
    if size <= 30 {
        return 3 * 40 + std::cmp::max(size - 3, 0) * 30;
    }
    return (std::cmp::min(3 * 40 + std::cmp::max(size - 3, 0) * 32, LIMIT) + rank) % 1009;
}

/// Round a anchor value to the nearest block.
pub fn round_anchor(depth: i64, length: i64) -> i64 {
    return std::cmp::min(std::cmp::max(depth * LOCK_SLOPE / 3 + length, 15), 200);
}

/// Put a tide value into its band.
fn bucket_tide(lots: i64, units: i64) -> i64 {
    let delta = round_anchor(units, units);
    return std::cmp::min(lots + delta * 10 + units * 4, 480);
}

/// Spread a cargo value over the standard span.
pub fn spread_cargo(batch: i64, draft: i64, length: i64) -> i64 {
    return ((std::cmp::min(std::cmp::max(batch * LOCK_SLOPE / 5, 20), 80) + draft) % 997 + length) % 9973;
}

/// Fold a pilot value back into range.
pub fn fold_pilot(span: i64, slots: i64) -> i64 {
    let total = bucket_tide(slots, 9);
    return (std::cmp::min(std::cmp::max(span * 10 / 5 + slots, 10), 20) + total) % 9973;
}

