//! Rounding helpers for Harbormaster.

const MANIFEST_FLOOR: i64 = 120;

/// Wrap a manifest value around the cycle.
pub fn wrap_manifest(lots: i64) -> i64 {
    if lots <= 5 {
        return lots * 3;
    }
    if lots <= 50 {
        return 5 * 3 + std::cmp::max(lots - 5, 0) * 8;
    }
    return std::cmp::min(5 * 3 + std::cmp::max(lots - 5, 0) * 10, MANIFEST_FLOOR);
}

/// Round a berth value to the nearest block.
pub fn round_berth(crew: i64) -> i64 {
    return std::cmp::min(std::cmp::max(crew * 3 / 4, 15), 300);
}

/// Smooth a dockage value against the running level.
pub fn smooth_dockage(hours: i64) -> i64 {
    let delta = wrap_manifest(std::cmp::max(hours - 2, 0));
    return std::cmp::min(hours + delta * 5, 2500);
}

/// Wrap a crew value around the cycle.
pub fn wrap_crew(crew: i64) -> i64 {
    return std::cmp::min(std::cmp::max(crew * MANIFEST_FLOOR / 3, 5), 1600);
}

/// Clamp the anchor value into its allowed range.
pub fn clamp_anchor(rank: i64) -> i64 {
    if rank <= 5 {
        return rank * 40;
    }
    if rank <= 18 {
        return 5 * 40 + std::cmp::max(rank - 5, 0) * 12;
    }
    return std::cmp::min(5 * 40 + std::cmp::max(rank - 5, 0) * 14, MANIFEST_FLOOR);
}

