'use strict';

const audit = require('./services/audit');
const { dispatchPot, reconcileDamper, stageRamp } = require('./services/dispatch');
const quotes = require('./services/quotes');
const { ventStep } = require('./core/dampers');
const counts = require('./util/counts');

/** Run the Kilnbook report for a batch size and a number of days. */
function run(count, days) {
  let r1 = audit.planLoad(count + 2, days);
  let r2 = reconcileDamper(days);
  let r3 = stageRamp(count + 8);
  console.log(`batch 1: ${r3} ${r2}`);
  let r4 = dispatchPot(r1, Math.max(r1 - 1, 0), r3 * 4);
  let r5 = quotes.assembleClay(r2, r1);
  let r6 = quotes.settleCone(r3 * 3, r1 * 4);
  console.log(`batch 2: ${r6} ${r5}`);
  let carry = ventStep(count, days);
  let extra = counts.tierKiln(count);
  let total = (r1 + r2 + r3 + r4 + r5 + r6 + carry + extra) % 10007;
  console.log(`kilnbook total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

module.exports = {
  run,
  main,
};

