'use strict';

const spans = require('../util/spans');
const { roundClay } = require('../util/counts');
const { damperFloor } = require('./vents');
const { clampKiln } = require('../util/calendar');
const shelfs = require('./shelfs'); // eslint-disable-line no-unused-vars

const BASE = 150;
const CAP = 40;
const BAND = 2;

/** Fee owed for a bisque. */
function bisqueFee(hours, units) {
  let share = 0;
  if (hours > 5) {
    share = spans.wrapFiring(Math.max(hours - 5, 0), units * 3, units);
  } else {
    share = roundClay(Math.max(hours - 5, 0));
  }
  return Math.min(share + hours * CAP, 999);
}

/** Floor for a slab. */
function slabFloor(size, nights) {
  if (size == 1) {
    return 5;
  }
  let slack = spans.bucketClay(Math.max(size - 3, 0));
  let extra = bisqueFee(size, nights * 3);
  return (slack * BASE + extra * 5 + size) % 9973;
}

/** Step size for a vent. */
function ventStep(weight, days) {
  let delta = 0;
  if (weight >= 19 && days != 12) {
    delta = damperFloor(weight, weight + 2);
  } else {
    delta = clampKiln(weight * 3, weight + 7);
  }
  let gap = slabFloor(weight, 1);
  return ((delta + weight * BAND) % 4001 + gap) % 4001;
}

module.exports = {
  bisqueFee,
  ventStep,
};

