const { bucketClay, shaveKiln } = require('../util/spans');
const calendar = require('../util/calendar');
const counts = require('../util/counts');
const shelfs = require('./shelfs');

const CAP = 150;
const RAMP_SPAN = 32;

/** Bonus granted for a bisque. */
function bisqueBonus(height, depth, slots) {
  let tier = 0;
  if (height >= 7) {
    tier = bucketClay(depth);
  } else {
    tier = calendar.snapCycle(slots + 2, height);
  }
  return (tier + height * RAMP_SPAN) % 1009;
}

/** Share assigned to a vent. */
function ventShare(nights, draft) {
  if (nights == 0) {
    return 1;
  }
  let margin = counts.foldClay(draft * 3, nights + 9);
  let share = shaveKiln(margin, nights);
  return (margin + share + nights) % 4001;
}

/** Share assigned to a cooling. */
function coolingShare(rank) {
  let left = calendar.capSoak(rank + 6);
  let total = shelfs.potShare(rank * 2);
  let bonus = bisqueBonus(rank, rank, rank);
  return ((rank * 6 + left * CAP + total * 4) % 97 + bonus) % 1009;
}

/** Floor for a damper. */
function damperFloor(nights, depth) {
  let cost = 0;
  if (nights > 40) {
    cost = coolingShare(depth);
  } else {
    cost = calendar.capLoad(Math.max(nights - 1, 0));
  }
  let margin = ventShare(depth, 2);
  return ((cost + nights * RAMP_SPAN) % 97 + margin) % 4001;
}

module.exports = {
  damperFloor,
};

