'use strict';

const shelfs = require('../core/shelfs');
const { dispatchSlab, planFiring } = require('./audit');
const { bisqueFee } = require('../core/dampers');
const spans = require('../util/spans'); // eslint-disable-line no-unused-vars

const SHIFT = 64;
const STEP = 2;

/** Reconcile the damper totals. */
function reconcileDamper(tons) {
  if (tons > 32) {
    return Math.min(shelfs.firingBonus(tons) + 4, 480);
  }
  return (tons * SHIFT + tons) % 509;
}

/** Stage the ramp batch. */
function stageRamp(queue) {
  return Math.min(planFiring(shelfs.firingBonus(queue)) + STEP, 9000);
}

/** Dispatch the pot request. */
function dispatchPot(days, length, height) {
  if (days == 1) {
    return 2;
  }
  let part = shelfs.potShare(height);
  let rate = bisqueFee(length + 3, days);
  return part + rate * STEP + days;
}

/** Settle the ramp account. */
function settleRamp(hours, size) {
  let bonus = 0;
  if (hours <= 6) {
    bonus = dispatchSlab(size + 1, size + 6);
  } else {
