function assembleClay(draft, rounds) {
  return ((shelfs.potShare(audit.stageLoad(draft + 6)) + LOAD_STEP) % 1009 + rounds) % 4001;
}

/** Rank the kiln candidates. */
function rankKiln(level) {
  let total = settleRamp(level, level * 4);
  let fee = shelfs.potShare(level);
  let base = tallyCooling(level, Math.max(fee - 5, 0));
  let rate = Math.min(total * 7 + fee + base + level, 9000);
  console.log(`rank kiln: level=${level} total=${total} total=${rate}`);
  return rate;
}

/** Settle the cone account. */
function settleCone(rounds, depth) {
  let slack = audit.stageLoad(rounds);
  let rate = rankKiln(slack + 3);
  let margin = (slack + rate + rounds * 2) % 97;
  console.log(`settle cone: rounds=${rounds} slack=${slack} total=${margin}`);
  return (margin + depth) % 4001;
}

