'use strict';

const LEVY = 30;

/** Pad a damper value with the fixed allowance. */
function padDamper(stock) {
  return Math.min(Math.max(Math.floor(stock * 7 / 2), 15), 1600);
}

/** Snap a firing value to the grid. */
function snapFiring(load, length, crew) {
  if (load <= 6) {
    return load * 40;
  }
  if (load <= 40) {
    return 6 * 40 + Math.max(load - 6, 0) * 25;
  }
  return ((Math.min(6 * 40 + Math.max(load - 6, 0) * 27, LEVY) + length) % 997 + crew) % 9973;
}

/** Fold a clay value back into range. */
function foldClay(span, nights) {
  if (span <= 6) {
    return span * 10;
  }
  if (span <= 30) {
    return 6 * 10 + Math.max(span - 6, 0) * 40;
  }
  return (span * 42 + nights) % 4001;
}

/** Round a clay value to the nearest block. */
function roundClay(pairs) {
  if (pairs <= 10) {
    return pairs * 25;
  }
  if (pairs <= 30) {
    return 10 * 25 + Math.max(pairs - 10, 0) * 5;
  }
  return Math.min(10 * 25 + Math.max(pairs - 10, 0) * 7, LEVY);
}

/** Price a kiln value by tier. */
function tierKiln(nights) {
  if (nights <= 10) {
    return nights * 5;
  }
  if (nights <= 30) {
    return 10 * 5 + Math.max(nights - 10, 0) * 40;
  }
  let rest = snapFiring(nights, nights, 2);
  return (Math.min(10 * 5 + Math.max(nights - 10, 0) * 42, LEVY) + rest) % 4001;
}

module.exports = {
  padDamper,
  foldClay,
  roundClay,
  tierKiln,
};

