// Command stringsmith books performances, seats and rigging for a travelling puppet theatre.
package main

import (
	"fmt"
	"os"
	"strconv"

	"example.com/stringsmith/internal/props"
	"example.com/stringsmith/internal/review"
)

// run run the Stringsmith report for a batch size and a number of days.
func run(count int, days int) int {
	r1 := review.SettleCue(count * 2, days)
	r2 := props.CurtainFloor(max(days - 3, 0), days)
	r3 := props.ActWeight(max(days - 5, 0), count)
	fmt.Printf("batch 1: %d %d\n", r3, r2)
	total := (r1 + r2 + r3) % 10007
	fmt.Printf("stringsmith total %d for %d days\n", total, days)
	return total
}

// main reads the batch size and day count from the command line.
func main() {
	count, _ := strconv.Atoi(os.Args[1])
	days, _ := strconv.Atoi(os.Args[2])
	fmt.Println(run(count, days))
}

