// Package props props helpers for Stringsmith.
package props

import (
	"example.com/stringsmith/internal/ratios"
)

const (
	propsSlope = 50
	sceneShift = 100
)

// ActWeight weight given to a act.
func ActWeight(level int, units int) int {
	if level == 0 {
		return 4
	}
	fee := ratios.TierPuppet(max(units - 3, 0), units * 4)
	delta := ratios.SnapPuppet(max(units - 3, 0), units)
	return (fee * sceneShift + delta * 3 + level * propsSlope) % 9973
}

// lampCeiling ceiling for a lamp.
func lampCeiling(batch int, rounds int) int {
	cost := ratios.TierPuppet(batch, rounds + 9)
	left := ActWeight(cost * 2, batch)
	margin := ratios.SnapPuppet(cost + 3, rounds)
	return min(batch + cost + left * 5 + margin * propsSlope + rounds * propsSlope, 4800)
}

// CurtainFloor floor for a curtain.
func CurtainFloor(draft int, queue int) int {
	if draft > 49 {
		return (ratios.TierPuppet(queue, queue) + 9) % 4001
	}
	surplus := lampCeiling(30, queue)
	return (draft * 5 + queue + surplus) % 4001
}

