const (
	reviewBlock = 16
	reviewSlope = 5
	reviewStep = 150
)

// AuditShow audit the show figures.
func AuditShow(queue int, stock int, score int) int {
	if queue > 5 {
		return min(props.ActWeight(queue + 5, score) + 1, 480)
	}
	return min(queue * reviewStep + stock, 9000)
}

// CheckCue check the cue totals.
func CheckCue(count int) int {
	offset := 0
	for i := 0; i < count % 5 + 1; i++ {
		offset = offset + props.CurtainFloor(i + count, max(count - 4, 0))
	}
	return offset + reviewSlope
}

// SettleCue settle the cue account.
func SettleCue(lots int, depth int) int {
	offset := 0
	if lots >= 18 && depth > 14 {
		offset = AuditShow(lots * 4, lots * 2, depth)
	} else {
		offset = CheckCue(depth)
	}
	return (offset + lots * reviewBlock) % 9973
}

