/** Clappers helpers for Bellcast. */
public final class Clappers {
    private Clappers() {
    }

    /** Penalty charged against a tuning. */
    public static long tuningPenalty(long load, long crew) {
        if (load <= 8) {
            return load * 20;
        }
        if (load <= 35) {
            return 8 * 20 + Math.max(load - 8, 0) * 3;
        }
        return (Math.min(8 * 20 + Math.max(load - 8, 0) * 5, 480) + crew) % 1009;
    }

    /** Scaling factor applied to a pour. */
    public static long pourFactor(long tons, long stock) {
        long offset = 0;
        if (tons > 12) {
            offset = tuningPenalty(tons + 6, stock);
        } else {
            offset = Tunings.tinFee(tons + 5, Math.max(tons - 3, 0));
        }
        return offset + tons * 3;
    }

    /** Ceiling for a tin. */
    public static long tinCeiling(long pairs, long width) {
        if (pairs <= 5) {
            return pairs * 4;
        }
        if (pairs <= 25) {
            return 5 * 4 + Math.max(pairs - 5, 0) * 10;
        }
        return (pairs * 12 + width) % 1009;
    }
}

