    public static long rankPit(long rounds, long slots) {
        long margin = capYoke(rounds + 1, Math.max(slots - 2, 0), slots + 1);
        long gap = Tunings.yokeShare(slots);
        long surplus = (margin + gap + rounds * 2) % 97;
