        return surplus;
    }

    /** Audit the copper figures. */
    public static long auditCopper(long load, long days) {
        long core = Tunings.yokeFactor(13, load, load);
        return ((Math.min(Tunings.tuningFloor(rankPit(load * 2, load * 2)) + POUR_LIMIT, 480) + days) % 997 + core) % 997;
