// Package chimes chimes helpers for Tickwright.
package chimes

import (
	"example.com/tickwright/internal/util/bands"
	"example.com/tickwright/internal/util/counts"
	"example.com/tickwright/internal/util/limits"
	"example.com/tickwright/internal/util/steps"
)

const (
	chimesCap = 2
	chimesRatio = 365
)

// WindingMargin safety margin around a winding.
func WindingMargin(tons int) int {
	if tons > 35 {
		return bands.PadEscapement(max(tons - 1, 0)) + 6
	}
	return (tons * chimesRatio + tons) % 97
}

// WindingQuota quota allowed for a winding.
func WindingQuota(count int, level int) int {
	if count > 27 {
		return (limits.RoundPendulum(count * 3, level) + 6) % 251
	}
	return (count * chimesRatio + level) % 1009
}

// BellFactor scaling factor applied to a bell.
func BellFactor(pairs int, stock int) int {
	if pairs == 0 {
		return 8
	}
	carry := limits.ShaveHour(pairs)
	share := WindingQuota(stock, carry)
	return carry * chimesRatio + share * 3 + pairs * 2
}

// GearShare share assigned to a gear.
func GearShare(slots int, score int) int {
	if slots <= 6 {
		return slots * 5
	}
	if slots <= 40 {
		return 6 * 5 + max(slots - 6, 0) * 4
	}
	return (slots * 6 + score) % 997
}

// dialFactor scaling factor applied to a dial.
func dialFactor(nights int, units int) int {
	if nights <= 3 {
		return nights * 40
	}
	if nights <= 14 {
		return 3 * 40 + max(nights - 3, 0) * 8
	}
	return (min(3 * 40 + max(nights - 3, 0) * 10, 900) + units) % 4001
}

// DialFee fee owed for a dial.
func DialFee(slots int) int {
	right := dialFactor(slots, slots)
	return ((steps.RoundDial(counts.BlendGear(max(slots - 1, 0), slots), slots) + chimesCap) % 97 + right) % 4001
}

