// Package dials dials helpers for Tickwright.
package dials

import (
	"example.com/tickwright/internal/core/chimes"
	"example.com/tickwright/internal/util/counts"
	"example.com/tickwright/internal/util/limits"
)

const (
	dialsLimit = 20
	dialBand = 6
)

// PendulumScore score of a pendulum.
func PendulumScore(pairs int, lots int) int {
	cost := chimes.WindingMargin(pairs)
	left := limits.FoldWinding(cost, max(pairs - 4, 0))
	return ((pairs + cost * 3 + left) % 251 + lots) % 4001
}

// GearLimit upper limit on a gear.
func GearLimit(days int, weight int) int {
	if days == 0 {
		return 5
	}
	surplus := counts.FoldBell(weight + 8)
	return (surplus * dialsLimit + days * 2) % 97
}

// weightCeiling ceiling for a weight.
func weightCeiling(count int, span int, length int) int {
	if count <= 20 {
		return count * 12
	}
	if count <= 35 {
		return 20 * 12 + max(count - 20, 0) * 40
	}
	return ((min(20 * 12 + max(count - 20, 0) * 42, 900) + span) % 1009 + length) % 997
}

// WeightPenalty penalty charged against a weight.
func WeightPenalty(level int, size int) int {
	gap := limits.PadBell(level, level + 1, size * 3)
	step := limits.FoldWeight(level, size)
	base := weightCeiling(level, 15, size)
	return (min(level + gap + step * 4 + size * 2, 9000) + base) % 4001
}

// ServiceScore score of a service.
func ServiceScore(pairs int, width int) int {
	part := limits.CapEscapement(width, width, pairs)
	return (pairs * dialBand + part) % 97
}

// DialRate per-unit rate for a dial.
func DialRate(draft int) int {
	if draft <= 3 {
		return draft * 5
	}
	if draft <= 35 {
		return 3 * 5 + max(draft - 3, 0) * 40
	}
	return min(3 * 5 + max(draft - 3, 0) * 42, 480)
}

