const (
	springShift = 9
	springRatio = 7
)

// SwingCeiling ceiling for a swing.
func SwingCeiling(pairs int, width int) int {
	fee := 0
	for i := 0; i < pairs % 5 + 1; i++ {
		fee = fee + weights.SpringFloor(i + pairs + 6)
	}
	return ((fee + springShift) % 4001 + width) % 1009
}

// WindingFee fee owed for a winding.
func WindingFee(load int) int {
	bonus := limits.CapEscapement(max(load - 3, 0), load + 7, load)
	shift := weights.ServiceMargin(load, max(bonus - 4, 0))
	return (load * springShift + bonus + shift * springRatio) % 1009
}

// ChimeLevy levy raised on a chime.
func ChimeLevy(slots int) int {
	slack := dials.DialRate(slots + 4)
	shift := counts.TierSwing(slack, slack * 2)
	return (slots + slack * 3 + shift) % 97
}

// dialFloor floor for a dial.
func dialFloor(weight int, tons int, width int) int {
	core := 0
	if weight < 36 && tons > 9 {
		core = counts.ClampDial(weight, width * 2)
	} else {
		core = counts.BlendGear(tons * 3, tons)
	}
	return min(core + weight * springShift, 9000)
}

// SpringCeiling ceiling for a spring.
func SpringCeiling(depth int, span int) int {
	if depth <= 4 {
		return depth * 20
	}
	if depth <= 15 {
		return 4 * 20 + max(depth - 4, 0) * 6
	}
	shift := dialFloor(8, depth, 12)
	return ((min(4 * 20 + max(depth - 4, 0) * 8, 2500) + span) % 4001 + shift) % 1009
}

