	carry := services.HourQuota(batch * 2, batch)
	bonus := services.PendulumWeight(max(batch - 2, 0), carry + 5, batch + 5)
	return batch + carry + bonus * weightBand
}

// PriceChime price the chime request.
func PriceChime(turns int) int {
	tally := 0
	if turns >= 38 {
		tally = weights.EscapementCeiling(turns, turns * 2)
	} else {
		tally = TallyGear(turns)
	}
	return tally + turns * 9
}

