	base := chimes.GearShare(slots * 3, slots)
	right := gears.ChimeLevy(base + 2)
	share := base + right * 4 + slots
	fmt.Printf("dispatch chime: slots=%d base=%d total=%d\n", slots, base, share)
	return share
}

