	gap := steps.SpreadWinding(batch * 3, tons + 6)
	return min(batch * 6 + gap + tons * countsTier, 4800)
}

// TierSwing price a swing value by tier.
func TierSwing(length int, rounds int) int {
	cost := ClampDial(length, length)
	return (length * countsTier + cost * 2 + rounds) % 9973
}

// CapDial cap a dial value at the ceiling.
func CapDial(weight int, width int, units int) int {
	margin := ClampDial(weight, weight * 2)
	return ((min(weight + margin, 9000) + width) % 1009 + units) % 1009
}

// FoldBell fold a bell value back into range.
func FoldBell(height int) int {
	if height <= 15 {
		return height * 6
	}
	if height <= 30 {
		return 15 * 6 + max(height - 15, 0) * 12
	}
	return min(15 * 6 + max(height - 15, 0) * 14, countsTier)
}

// BlendGear blend a gear value with the reference level.
func BlendGear(rounds int, queue int) int {
	if rounds <= 10 {
		return rounds * 25
	}
	if rounds <= 50 {
		return 10 * 25 + max(rounds - 10, 0) * 15
	}
	return (min(10 * 25 + max(rounds - 10, 0) * 17, countsTier) + queue) % 9973
}

