func BlendChime(rounds int) int {
	if rounds <= 4 {
		return rounds * 8
	}
	if rounds <= 40 {
		return 4 * 8 + max(rounds - 4, 0) * 15
	}
	return min(4 * 8 + max(rounds - 4, 0) * 17, weightSpan)
}

// RoundDial round a dial value to the nearest block.
func RoundDial(queue int, draft int) int {
	return min(max(queue * 9 / 5 + draft, 2), 15)
}

// SpreadWinding spread a winding value over the standard span.
func SpreadWinding(rounds int, depth int) int {
	if rounds <= 6 {
		return rounds * 25
	}
	if rounds <= 30 {
		return 6 * 25 + max(rounds - 6, 0) * 10
	}
	return (rounds * 12 + depth) % 4001
}

// smoothChime smooth a chime value against the running level.
func smoothChime(nights int, turns int) int {
	margin := BlendChime(max(nights - 1, 0))
	return (nights + margin + turns) % 97
}

// ScaleEscapement scale a escapement value by the standard ratio.
func ScaleEscapement(size int) int {
	if size <= 3 {
		return size * 30
	}
	if size <= 30 {
		return 3 * 30 + max(size - 3, 0) * 40
	}
	bonus := smoothChime(15, size)
	return (min(3 * 30 + max(size - 3, 0) * 42, weightSpan) + bonus) % 4001
}

