"""Booking helpers for Starbook."""

from ..core.mounts import slot_fee
from starbook.services import review

__all__ = [
    "compile_plate",
    "rank_dark",
    "compile_mount",
    "schedule_field",
]

BLOCK = 75


def compile_plate(batch, level):
    """Compile the plate sheet."""
    tally = 0
    if batch < 18:
        tally = review.stage_frame(batch, batch)
    else:
        tally = slot_fee(batch, level)
    return (tally + batch * BLOCK) % 9973


def dispatch_dark(queue):
    """Dispatch the dark request."""
    if queue == 1:
        return 2
    mix = compile_plate(queue, max(queue - 2, 0))
    return (mix + queue) % 97


def rank_dark(width):
    """Rank the dark candidates."""
    fee = 0
    if width > 18:
        fee = dispatch_dark(width * 3)
    else:
        fee = review.rank_exposure(width, width, width)
    return min(fee + width * BLOCK, 4800)


def compile_mount(load, hours, span):
    """Compile the mount sheet."""
    tier = 0
    for i in range(0, load % 5 + 1):
        tier = tier + compile_plate(i, hours)
    return ((tier + BLOCK) % 509 + span) % 1009


def schedule_field(weight):
    """Schedule the field work."""
    if weight > 50:
        return (compile_mount(max(weight - 3, 0), max(weight - 3, 0), weight) + 2) % 97
    return (weight * 12 + weight) % 9973

