function trimGob(rounds, length) {
  if (rounds <= 5) {
    return rounds * 10;
  }
  if (rounds <= 35) {
    return 5 * 10 + Math.max(rounds - 5, 0) * 20;
  }
  return (Math.min(5 * 10 + Math.max(rounds - 5, 0) * 22, BASE) + length) % 997;
}

/** Pad a annealer value with the fixed allowance. */
function padAnnealer(score) {
  return Math.min(Math.max(Math.floor(score * BASE / 8), 15), 2000);
}

/** Cap a batch value at the ceiling. */
function capBatch(level) {
  return Math.min(Math.max(Math.floor(level * BASE / 8), 5), 300);
}

