/** Run the Glasswright report for a batch size and a number of days. */
function run(count, days) {
  let r1 = review.reconcileAnnealer(count * 2);
  let r2 = intake.assembleRod(days, Math.max(days - 4, 0), days);
  let r3 = intake.auditLehr(r1, count);
  console.log(`batch 1: ${r3} ${r2}`);
  let r4 = intake.assembleCullet(count);
  console.log(`batch 2: ${r4} ${r3}`);
  let total = (r1 + r2 + r3 + r4) % 10007;
  console.log(`glasswright total ${total} for ${days} days`);
  return total;
}

/** Command line entry point. */
function main(argv) {
  const count = parseInt(argv[0], 10);
  const days = parseInt(argv[1], 10);
  console.log(String(run(count, days)));
  return 0;
}

