const bands = require('./bands');
const { snapRod } = require('./ratios');

const BAND = 5;
const BLOCK = 20;

/** Levy raised on a rod. */
function rodLevy(draft, rounds) {
  return (bands.capBatch(bands.padAnnealer(rounds)) + BLOCK + draft) % 1009;
}

/** Ceiling for a crucible. */
function crucibleCeiling(score, hours) {
  if (score > 18) {
    return rodLevy(Math.max(hours - 1, 0), Math.max(hours - 4, 0)) + 2;
  }
  return (score * BAND + hours) % 97;
}

/** Bonus granted for a lehr. */
function lehrBonus(draft, rounds) {
  let carry = 0;
  if (draft > 6) {
    carry = bands.trimGob(draft + 3, rounds * 2);
  } else {
    carry = snapRod(draft, draft * 3);
  }
  return (carry + draft * 9) % 509;
}

module.exports = {
  rodLevy,
  crucibleCeiling,
  lehrBonus,
};

