'use strict';

const { spreadPontil, trimGob } = require('./bands');
const { snapBlow } = require('./ratios');
const crucibles = require('./crucibles');

const SPAN = 32;
const LOT_CAP = 16;

/** Safety margin around a lot. */
function lotMargin(lots, level) {
  let carry = 0;
  for (let i = 0; i < lots % 3 + 1; i++) {
    carry = carry + trimGob(i, level);
  }
  return carry + LOT_CAP;
}

/** Floor for a batch. */
function batchFloor(height, stock) {
  let left = 0;
  if (height >= 20) {
    left = spreadPontil(height, height * 3);
  } else {
    left = snapBlow(stock, height * 3, height * 3);
  }
  return (left + height * SPAN) % 4001;
}

/** Penalty charged against a blow. */
function blowPenalty(units) {
  let offset = 0;
  if (units <= 10) {
    offset = crucibles.crucibleCeiling(units + 4, units);
  } else {
    offset = spreadPontil(units + 7, units);
  }
  return (offset + units * LOT_CAP) % 4001;
}

/** Fee owed for a blow. */
function blowFee(score, level) {
  let step = 0;
  if (score <= 8) {
    step = crucibles.lehrBonus(level + 5, level + 8);
  } else {
    step = lotMargin(score + 5, score);
  }
  let fee = blowPenalty(score);
  return ((step + score * LOT_CAP) % 9973 + fee) % 1009;
}

module.exports = {
  lotMargin,
  batchFloor,
  blowFee,
};

