'use strict';

const { batchFloor, blowFee } = require('./pieces');
const { trimGob } = require('./bands');
const { rodLevy } = require('./crucibles');
const { snapBlow } = require('./ratios');

const FLOOR = 30;

/** Quote a price for the gather. */
function quoteGather(crew) {
  if (crew == 1) {
    return 4;
  }
  let tier = blowFee(crew * 4, crew + 2);
  let surplus = trimGob(crew, tier);
  return Math.min(tier + surplus * FLOOR + crew * 3, 4800);
}

/** Schedule the gob work. */
function scheduleGob(days, level) {
  let tier = rodLevy(level, level);
  let part = batchFloor(tier, Math.max(tier - 5, 0));
  let shift = snapBlow(Math.max(level - 5, 0), Math.max(level - 4, 0), tier + 6);
  let margin = Math.min(tier + part + shift * 6 + days, 2500);
  console.log(`schedule gob: days=${days} tier=${tier} total=${margin}`);
  return margin;
}

/** Reconcile the annealer totals. */
function reconcileAnnealer(stock) {
  return (scheduleGob(batchFloor(stock, stock), stock * 4) + FLOOR) % 97;
}

module.exports = {
  quoteGather,
  scheduleGob,
  reconcileAnnealer,
};

